#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "config/config.h"
#include "core/core.h"

// Where the docs that generated links point to live, relative to the repository root
#define FITNESS_DOC    "docs/fitness.md"
#define ALGORITHM_DOCS "docs/algorithms"

#define BLOCK_OPEN  "<!-- gen:"
#define BLOCK_CLOSE "<!-- /gen -->"
#define BLOCK_NOTE \
  "<!-- Generated by `make docs` from the source tables; edits here are overwritten -->"

// --- Files ---

typedef struct {
  char*  data;
  size_t len;
} Text;

// The whole file at `path`; data is NULL when it can't be opened
static Text read_file(const char* path) {
  Text  t = {NULL, 0};
  FILE* f = fopen(path, "rb");
  if (!f) return t;
  if (fseek(f, 0, SEEK_END) != 0) die("can't read '%s'", path);
  long size = ftell(f);
  if (size < 0 || fseek(f, 0, SEEK_SET) != 0) die("can't read '%s'", path);
  t.data = xmalloc((size_t) size + 1);
  t.len  = fread(t.data, 1, (size_t) size, f);
  if (t.len != (size_t) size || ferror(f)) die("can't read '%s'", path);
  t.data[t.len] = '\0';
  fclose(f);
  return t;
}

// Written to a temporary file first, so a failure never leaves `path` half-written
static void write_file(const char* path, const char* data, size_t len) {
  char tmp[PATH_MAX];
  if (snprintf(tmp, sizeof(tmp), "%s.tmp", path) >= (int) sizeof(tmp)) die("path too long");
  FILE* f = fopen(tmp, "wb");
  if (!f) die("can't write '%s'", tmp);
  if (fwrite(data, 1, len, f) != len || fclose(f) != 0) die("can't write '%s'", tmp);
  if (rename(tmp, path) != 0) die("can't replace '%s'", path);
}

// --- Links ---

// Writes the link from the doc at `from` to `to`, both relative to the repository root: the
// directories they share are dropped, and every other directory of `from` becomes a "../"
// Empty when both are the same file, so an anchor can follow
static void write_link(FILE* out, const char* from, const char* to) {
  if (strcmp(from, to) == 0) return;
  size_t shared = 0;
  for (size_t i = 0; from[i] && from[i] == to[i]; i++)
    if (from[i] == '/') shared = i + 1;
  for (const char* p = from + shared; *p; p++)
    if (*p == '/') fputs("../", out);
  fputs(to + shared, out);
}

// The text of the first "# " heading in the doc at `path`, or NULL when there's no such doc or
// heading
static char* doc_title(const char* path) {
  Text doc = read_file(path);
  if (!doc.data) return NULL;
  char* title = NULL;
  for (char* line = doc.data; line && !title;) {
    if (strncmp(line, "# ", 2) == 0) {
      size_t len = strcspn(line + 2, "\r\n");
      title      = xmalloc(len + 1);
      memcpy(title, line + 2, len);
      title[len] = '\0';
    }
    line = strchr(line, '\n');
    if (line) line++;
  }
  free(doc.data);
  return title;
}

// --- Blocks ---

// A table cell: a `|` would end the cell, so it's escaped
static void write_cell(FILE* out, const char* s) {
  for (; *s; s++) {
    if (*s == '|') fputc('\\', out);
    fputc(*s, out);
  }
}

// A row's choices, from wherever its type keeps them; empty for a free value
static void write_values(FILE* out, const FieldSpec* row) {
  const char* sep = "";
  switch (row->type) {
    case FIELD_ENUM:
      for (const EnumEntry* c = row->lookup; c->name; c++, sep = ", ")
        fprintf(out, "%s`%s`", sep, c->name);
      break;
    case FIELD_ALGORITHM:
      for (int i = 0; algorithms[i]; i++, sep = ", ")
        fprintf(out, "%s`%s`", sep, algorithms[i]->name);
      break;
    case FIELD_FITNESS:
      for (int i = 0; fitness_at(i); i++, sep = ", ")
        fprintf(out, "%s`%s`", sep, fitness_name(fitness_at(i)));
      break;
    case FIELD_BOOL: fputs("`true`, `false`", out); break;
    default:         break;
  }
}

// The rows of `table` whose scope is exactly `scope`, or every row when `scope` is 0
// Defaults are code, except the parenthesized placeholders like "(unset)"
static void write_fields(FILE* out, const FieldSpec* table, unsigned scope) {
  fputs("| Key | Type | Default | Values | Description |\n", out);
  fputs("|-----|------|---------|--------|-------------|\n", out);
  for (const FieldSpec* row = table; row->name; row++) {
    if (scope && row->scope != scope) continue;
    const char* def  = field_default_display(row);
    int         code = def[0] != '(' && strcmp(def, "-") != 0;
    fprintf(out, "| `%s` | %s | %s", row->name, field_type_label(row->type), code ? "`" : "");
    write_cell(out, def);
    fprintf(out, "%s | ", code ? "`" : "");
    write_values(out, row);
    fputs(" | ", out);
    write_cell(out, row->description ? row->description : "");
    fputs(" |\n", out);
  }
}

// "common,run" as the scope it names; dies on an unknown section
static unsigned parse_scope(const char* list) {
  static const struct {
    const char* name;
    Section     bit;
  } sections[] = {
      {"common",   SECTION_COMMON  },
      {"run",      SECTION_RUN     },
      {"defaults", SECTION_DEFAULTS},
  };
  unsigned scope = 0;
  while (*list) {
    size_t len   = strcspn(list, ",");
    int    found = 0;
    for (size_t i = 0; i < sizeof(sections) / sizeof(sections[0]); i++) {
      if (strlen(sections[i].name) == len && strncmp(list, sections[i].name, len) == 0) {
        scope |= sections[i].bit;
        found  = 1;
      }
    }
    if (!found) die("unknown section '%.*s' (expected common, run or defaults)", (int) len, list);
    list += len + (list[len] == ',');
  }
  return scope;
}

// `fields runner <sections>`: the runner rows with exactly that scope, e.g. "common,run"
// `fields <algorithm>`: every row of that algorithm
static void write_fields_block(FILE* out, const char* args) {
  char what[64], sections[64] = "";
  if (sscanf(args, "%63s %63s", what, sections) < 1) die("'fields' needs a table name");

  if (strcmp(what, "runner") == 0) {
    if (!sections[0]) die("'fields runner' needs its sections, e.g. 'fields runner common,run'");
    unsigned scope = parse_scope(sections);
    int      any   = 0;
    for (const FieldSpec* row = runner_fields; row->name; row++) any |= row->scope == scope;
    if (!any) die("no runner field is allowed in exactly '%s'", sections);
    write_fields(out, runner_fields, scope);
    return;
  }

  if (sections[0]) die("'fields %s' takes no sections", what);
  int i = find_algorithm(what);
  if (i < 0) die("unknown algorithm '%s'", what);
  write_fields(out, algorithms[i]->fields, 0);
}

// One line per algorithm, linking its doc by the doc's title; a bare name when it has no doc yet
static void write_algorithms_block(FILE* out, const char* doc) {
  for (int i = 0; algorithms[i]; i++) {
    const char* name = algorithms[i]->name;
    char        path[PATH_MAX];
    snprintf(path, sizeof(path), "%s/%s.md", ALGORITHM_DOCS, name);
    char* title = doc_title(path);
    if (!title) {
      fprintf(out, "- `%s`\n", name);
      continue;
    }
    fprintf(out, "- [%s](", title);
    write_link(out, doc, path);
    fprintf(out, ") (`%s`)\n", name);
    free(title);
  }
}

// One row per catalog function, linking its section of the fitness doc
static void write_fitness_block(FILE* out, const char* doc) {
  fputs("| Function | `n_dims` | Domain |\n", out);
  fputs("|----------|----------|--------|\n", out);
  for (int i = 0; fitness_at(i); i++) {
    const char* name = fitness_name(fitness_at(i));
    char        dims[FITNESS_LIMIT_LEN], domain[FITNESS_LIMIT_LEN];
    fitness_limits_text(fitness_at(i), dims, domain);
    fprintf(out, "| [`%s`](", name);
    write_link(out, doc, FITNESS_DOC);
    fprintf(out, "#%s) | %s | %s |\n", name, dims, domain);
  }
}

// `spec` is what follows "gen:" in the opening marker: a block name, then its arguments
static void write_block(FILE* out, const char* doc, const char* spec) {
  char name[32];
  int  n = 0;
  if (sscanf(spec, "%31s%n", name, &n) != 1) die("empty block name");
  const char* args = spec + n + strspn(spec + n, " ");

  if (strcmp(name, "fields") == 0) {
    write_fields_block(out, args);
    return;
  }
  if (strcmp(name, "algorithms") != 0 && strcmp(name, "fitness") != 0)
    die("unknown block '%s' (expected fields, algorithms or fitness)", name);
  if (*args) die("'%s' takes no arguments", name);
  if (strcmp(name, "algorithms") == 0) write_algorithms_block(out, doc);
  else write_fitness_block(out, doc);
}

// --- Docs ---

// The line from `start` without its line ending or surrounding blanks, into `buf`
static void trimmed(const char* start, size_t len, char* buf, size_t size) {
  while (len && (*start == ' ' || *start == '\t')) start++, len--;
  while (len && strchr(" \t\r\n", start[len - 1])) len--;
  if (len >= size) len = size - 1;
  memcpy(buf, start, len);
  buf[len] = '\0';
}

// `doc` with every block regenerated; text outside the blocks is copied as is
// Markers inside fenced code blocks are text, so a doc can show the syntax
static char* regenerate(const char* doc, const Text* src, size_t* out_len) {
  char* buf;
  FILE* out = open_memstream(&buf, out_len);
  if (!out) die("memory allocation failed");

  static char where[PATH_MAX + 32];
  int         in_fence = 0, in_block = 0, open_line = 0;
  const char* line = src->data;
  for (int n = 1; line < src->data + src->len; n++) {
    const char* end = memchr(line, '\n', (size_t) (src->data + src->len - line));
    size_t      len = end ? (size_t) (end - line) + 1 : (size_t) (src->data + src->len - line);
    char        t[256];
    trimmed(line, len, t, sizeof(t));
    snprintf(where, sizeof(where), "%s:%d", doc, n);
    g_where = where;

    int opens  = !in_fence && strncmp(t, BLOCK_OPEN, strlen(BLOCK_OPEN)) == 0;
    int closes = !in_fence && strcmp(t, BLOCK_CLOSE) == 0;
    if (opens && in_block) die("block opened inside the block from line %d", open_line);
    if (closes && !in_block) die("'%s' without an opening marker", BLOCK_CLOSE);
    if (!in_block && (strncmp(t, "```", 3) == 0 || strncmp(t, "~~~", 3) == 0)) in_fence = !in_fence;

    if (opens) {
      size_t tl = strlen(t);
      if (tl < strlen(BLOCK_OPEN) + 3 || strcmp(t + tl - 3, "-->") != 0)
        die("opening marker doesn't end with '-->'");
      t[tl - 3] = '\0';
      char spec[256];
      trimmed(t + strlen(BLOCK_OPEN), strlen(t + strlen(BLOCK_OPEN)), spec, sizeof(spec));
      fwrite(line, 1, len, out);
      fprintf(out, "%s\n\n", BLOCK_NOTE);
      write_block(out, doc, spec);
      fputc('\n', out);
      in_block  = 1;
      open_line = n;
    } else if (closes) {
      fwrite(line, 1, len, out);
      in_block = 0;
    } else if (!in_block) {
      fwrite(line, 1, len, out);
    }
    line += len;
  }
  if (in_block) {
    snprintf(where, sizeof(where), "%s:%d", doc, open_line);
    die("block never closed: '%s' missing", BLOCK_CLOSE);
  }
  g_where = NULL;

  if (fclose(out) != 0) die("memory allocation failed");
  return buf;
}

// Every doc is regenerated before any is written, so an error in one leaves all of them untouched
int main(int argc, char** argv) {
  if (argc < 2) die("usage: gen-docs DOC...");

  char**  outputs = xcalloc((size_t) argc, sizeof(char*));
  size_t* lens    = xcalloc((size_t) argc, sizeof(size_t));
  Text*   srcs    = xcalloc((size_t) argc, sizeof(Text));
  for (int i = 1; i < argc; i++) {
    // Links are worked out from the doc's path, so it has to be relative to the repository root
    if (argv[i][0] == '/' || strstr(argv[i], "./"))
      die("'%s': docs are named relative to the repository root, without . or ..", argv[i]);
    srcs[i] = read_file(argv[i]);
    if (!srcs[i].data) die("can't read '%s'", argv[i]);
    outputs[i] = regenerate(argv[i], &srcs[i], &lens[i]);
  }

  for (int i = 1; i < argc; i++) {
    if (lens[i] == srcs[i].len && memcmp(outputs[i], srcs[i].data, lens[i]) == 0) continue;
    write_file(argv[i], outputs[i], lens[i]);
    printf("updated %s\n", argv[i]);
  }
  return EXIT_SUCCESS;
}
